// ===================== TASK GENERATOR =====================
const identifyTaskDB=[{"s":"Acuñó la palabra hacia 1796 como nombre de una ciencia.","type":"Destutt de Tracy"},{"s":"Convirtió «ideólogos» en burla.","type":"Napoleón"},{"s":"La imagen que muestra el mundo invertido.","type":"La cámara oscura"},{"s":"Escrita en 1845 a 1846, publicada completa en 1932.","type":"La ideología alemana"},{"s":"La carta del 14 de julio de 1893.","type":"La fuente real de «falsa conciencia» (Engels a Mehring)"},{"s":"Convierte toda objeción en síntoma del que objeta.","type":"La autoinmunización"},{"s":"La salida de Mannheim que no es relativismo.","type":"El relacionismo"},{"s":"La ideología no es patología sino esto.","type":"Un mapa (Geertz, 1964)"},{"s":"«Ideología» para el otro, «sentido común» para mí.","type":"El uso tramposo"},{"s":"Un desenmascaramiento propio por cada ajeno.","type":"La regla de pago"}];
const classifyTaskDB=[{"w":"Destutt de Tracy","gen":"Origen","n":"Acuñó la palabra hacia 1796","g":"Elementos de ideología, 1801 a 1815","t":"Clásico de historia de las ideas"},{"w":"Napoleón","gen":"Torcedura","n":"Volvió «ideólogos» una burla","g":"La palabra nunca se recuperó","t":"Dato histórico del expediente"},{"w":"La ideología alemana","gen":"Fuente primaria","n":"La cámara oscura y las ideas dominantes","g":"Escrita 1845 a 1846","t":"Publicada completa en 1932"},{"w":"La cámara oscura","gen":"Imagen","n":"El mundo mostrado al revés","g":"Marx y Engels","t":"Potente, y con problema adentro"},{"w":"Carta a Franz Mehring","gen":"Fuente real","n":"Aquí sí aparece «falsa conciencia»","g":"Engels, 14 de julio de 1893","t":"No está en la obra publicada de Marx"},{"w":"La autoinmunización","gen":"Defecto","n":"Despierto entre dormidos","g":"La crítica del mismo día","t":"Lo que todo lo explica nada prohíbe"},{"w":"Ideología y utopía","gen":"Fuente","n":"El giro del instrumento hacia adentro","g":"Mannheim, 1929","t":"Clásico sólido con debates vivos"},{"w":"El relacionismo","gen":"Concepto","n":"Cada mirada tiene lugar, y unas alumbran más","g":"Mannheim","t":"No es relativismo"},{"w":"La ideología como sistema cultural","gen":"Fuente","n":"La ideología es mapa, no patología","g":"Geertz, 1964 y 1973","t":"Clásico sólido"},{"w":"La regla de pago","gen":"Protocolo","n":"Uno propio por cada ajeno","g":"La mesa de la casa","t":"Sin ella, el detector es arma"}];
const completeTaskDB=[{"s":"La palabra nació como el nombre de una ___.","opts":["ciencia","burla","ley"],"ans":"ciencia"},{"s":"Napoleón convirtió «ideólogos» en ___.","opts":["burla","ciencia","partido"],"ans":"burla"},{"s":"La ideología invierte el mundo como una cámara ___.","opts":["oscura","lenta","clara"],"ans":"oscura"},{"s":"«Falsa conciencia» aparece en la carta a ___.","opts":["Mehring","Marx","Geertz"],"ans":"Mehring"},{"s":"La ideología alemana se publicó completa en ___.","opts":["1932","1846","1929"],"ans":"1932"},{"s":"Mannheim llamó a su salida ___.","opts":["relacionismo","relativismo","realismo"],"ans":"relacionismo"},{"s":"Para Geertz la ideología es un ___.","opts":["mapa","delito","síntoma"],"ans":"mapa"},{"s":"Cada desenmascaramiento ajeno se paga con uno ___.","opts":["propio","ajeno","prestado"],"ans":"propio"}];
const explainQuestions=[{"q":"¿Por qué el dato de 1796 cambia toda la discusión? Explícalo con el caso del padre que escribe «no metan ideología en las fichas».","ans":"Porque cambia quién carga la prueba. Si «ideología» fuera de nacimiento el nombre del error ajeno, el que la usa no debería explicar nada: le basta señalar. Pero la palabra fue acuñada hacia 1796 por Antoine Destutt de Tracy para nombrar una ciencia, el estudio de cómo se forman las ideas en cualquier cabeza, incluida la del que estudia. Con ese dato, el padre que escribe «no metan ideología en las fichas» ya no está describiendo la ficha: está usando una acusación, y lo que le toca es decir qué afirmación concreta le parece preferencia disfrazada de descripción. Y a la casa le toca lo mismo, en la misma hoja y esa misma semana."},{"q":"Cuenta cómo la palabra pasó de ciencia a insulto, y por qué eso sigue trabajando hoy.","ans":"Destutt de Tracy la acuñó hacia 1796 como el nombre de una ciencia y publicó sus «Elementos de ideología» entre 1801 y 1815. A Napoleón le estorbaban esos intelectuales que le objetaban con razones, y empezó a llamarlos «ideólogos» con desprecio: gente de ideas sin realidad. El desprecio prosperó más que la ciencia y la palabra nunca se recuperó: nació ciencia y quedó insulto. Sigue trabajando hoy porque el insulto conserva su dirección original, hacia afuera: nadie dice «mi ideología». Cada vez que se usa para señalar al bando contrario se repite la burla del emperador, con la ventaja retórica de que suena a análisis."},{"q":"¿Qué dice la cámara oscura, qué enseña bien, y qué problema trae adentro?","ans":"Marx y Engels, en «La ideología alemana» (escrita en 1845 a 1846 y publicada completa en 1932), dijeron que la ideología invierte el mundo como en una cámara oscura, porque las ideas dominantes de una época son las ideas de la clase dominante. Enseña bien una cosa: las ideas tienen dueño y dirección, no caen del cielo, así que conviene preguntar a quién le conviene que algo parezca obvio. El problema que trae adentro es que supone una posición desde la cual el mundo se ve derecho y no dice cuál, y si el instrumento se aplica solo hacia afuera, se vuelve una llave que abre todas las puertas menos la propia. Ese es el problema que Mannheim recogió y giró."},{"q":"¿De dónde sale la frase «falsa conciencia» y por qué el matiz es medio módulo?","ans":"La frase exacta no está en la obra publicada de Marx, aunque a él se le atribuya casi siempre: es de Engels, en su carta a Franz Mehring del 14 de julio de 1893. El matiz es medio módulo por dos razones. La primera es de honestidad de fuentes: el concepto más citado del tema resulta ser una frase de correspondencia privada, escrita casi medio siglo después de la obra a la que se le cuelga, y una materia que enseña a pedir fuentes no puede empezar fallando en la propia. La segunda es de método: el concepto se autoinmuniza, porque quien diagnostica falsa conciencia se declara despierto entre dormidos y convierte cada desacuerdo en síntoma del otro. Lo que explica cualquier respuesta no prohíbe ninguna, y una teoría que no prohíbe nada no informa de nada."},{"q":"Explica la diferencia entre relacionismo y relativismo, con el ejemplo de dos mapas.","ans":"Mannheim, en «Ideología y utopía» (1929), aceptó la consecuencia incómoda de su propio instrumento: si toda posición social produce su punto de vista, el que desenmascara también mira desde algún lado. A esa posición la llamó relacionismo, y se cuidó de distinguirla del relativismo, que sostiene que entonces todo da igual. El ejemplo son dos mapas del mismo terreno: los dos son parciales, los dos eligen qué dibujar y qué dejar afuera, y aun así uno te lleva al río y el otro te pierde. Que toda mirada tenga lugar de origen no borra la diferencia entre mirar bien y mirar mal: solo obliga a declarar desde dónde se mira antes de discutir."},{"q":"¿Por qué esta materia obliga a girar el detector hacia adentro, y cómo se cumple en esta casa?","ans":"Porque diseccionar el ideario del bando contrario lo hace cualquiera y auditar el propio no lo hace casi nadie, así que un detector que solo suena con un bando está descompuesto: no es instrumento, es arma. Y porque la trampa propia de la materia es la peor de todas, el alumno que aprende a ver gafas ajenas y se cree descalzo; la vacuna es Mannheim, que demostró que nadie mira desde ningún lado. En esta casa se cumple con la regla de pago: cada desenmascaramiento ajeno se paga con uno propio, esa misma semana. Por eso las tres premisas de la casa (la fe, el proyecto educativo y el emprendimiento) entran al inventario de gafas con su núcleo declarado y con el renglón de qué evidencia haría cambiar cada una; si ese renglón no existe, la premisa está funcionando como dogma, y así se anota, con fecha."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Acuñó la palabra hacia 1796 como nombre de una ciencia. → <span style="color:var(--jade);font-weight:700;">Destutt de Tracy</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

