// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1796","icon":"⚗️","label":"Nace la palabra","text":"<strong>Antoine Destutt de Tracy</strong> acuña «ideología» como el nombre de <strong>una ciencia</strong>: el estudio de cómo se forman las ideas, <strong>en cualquier cabeza</strong>, incluida la del que estudia. La palabra nace como espejo y no como dedo."},{"y":"1801 a 1815","icon":"📚","label":"Elementos de ideología","text":"Sale la obra de Destutt de Tracy. Entra con su etiqueta: <strong>clásico de historia de las ideas</strong>, y se cita <strong>por el origen del término</strong>, no se lee entera. Saber eso es parte de la honestidad de fuentes de la etapa."},{"y":"Poco después","icon":"🗣️","label":"Napoleón y la burla","text":"Al emperador le estorban esos intelectuales que le objetan con razones, y empieza a llamarlos <strong>«ideólogos» con desprecio</strong>: gente de ideas sin realidad. El desprecio prospera más que la ciencia: <strong>nació ciencia y quedó insulto</strong>."},{"y":"1845 a 1846","icon":"📷","label":"La cámara oscura","text":"Marx y Engels escriben <strong>«La ideología alemana»</strong>: las ideas dominantes son las de la clase dominante, y la ideología <strong>invierte el mundo como en una cámara oscura</strong>. Se publica completa <strong>en 1932</strong>: durmió ochenta y seis años."},{"y":"1893","icon":"✉️","label":"La carta a Mehring","text":"<strong>La nota honesta:</strong> «falsa conciencia» <strong>no está en la obra publicada de Marx</strong>. Es de <strong>Engels, en su carta a Franz Mehring del 14 de julio de 1893</strong>. Y trae trampa: quien la diagnostica <strong>se declara despierto entre dormidos</strong>."},{"y":"1929","icon":"🔭","label":"Mannheim se muerde la cola","text":"En <strong>«Ideología y utopía»</strong> gira el instrumento hacia sí mismo: si toda posición produce su punto de vista, <strong>el desenmascarador también mira desde algún lado</strong>. Lo llama <strong>relacionismo</strong>, para no caer en el relativismo."},{"y":"1964","icon":"🗺️","label":"Geertz baja la temperatura","text":"<strong>«La ideología como sistema cultural»</strong> (recogido en <strong>«La interpretación de las culturas», 1973</strong>): la ideología <strong>no es patología sino mapa</strong>, y aparece donde los mapas heredados dejaron de servir. <strong>Nadie mira a ojo desnudo.</strong>"}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(expediente){sfx(expediente?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(expediente){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">👓</span><span class="ms-text"><strong>La casa contestó con los dos mapas:</strong> qué da por obvio el que acusa y qué da por sentado M.E.T.A.S, con cifras de quién lo paga y sin usar una palabra del vocabulario ajeno. Angelly entendió que la palabra no era un insulto: era una pregunta.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">💳</span><span class="ms-text"><strong>Y el desenmascaramiento se pagó:</strong> esa misma semana la casa anotó una premisa propia que nadie discute nunca, con su renglón de qué evidencia la haría cambiar. El detector quedó calibrado en las dos direcciones.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🪤</span><span class="ms-text"><strong>La trampa quedó impresa:</strong> «lo nuestro es sentido común» reserva la palabra para el bando contrario, que es exactamente el uso que Napoleón inauguró. La casa acaba de hacer, en voz alta, lo que la etapa enseña a cazar.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🙋</span><span class="ms-text"><strong>Y Angelly aprendió lo contrario de lo que se quería enseñar:</strong> que la palabra sirve para señalar afuera. Se corrige esa misma noche, con la versión de Geertz: una ideología es un mapa, y en esta casa el mapa se pone sobre la mesa.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"tracy":{"nombre":"La palabra que nació ciencia","icon":"⚗️","estructura":{"title":"Qué es","info":"• Acuñada hacia <strong>1796</strong> por <strong>Destutt de Tracy</strong><br>• Nombre de una <strong>ciencia</strong>: cómo se forman las ideas<br>• Y en <strong>cualquier cabeza</strong>, incluida la del que estudia"},"funcion":{"title":"Cómo se reconoce","info":"• Cuando la palabra <strong>se aplica también a quien habla</strong><br>• Cuando trae fecha y autor, y no solo un dedo apuntando<br>• Su obra, <strong>«Elementos de ideología» (1801 a 1815)</strong>, se cita por el origen"},"enfermedades":{"title":"Dónde se cae","info":"• Usarla como <strong>burla napoleónica</strong> sin saberlo<br>• Creer que la inventó Marx: <strong>es medio siglo anterior</strong><br>• Leerla entera cuando <strong>solo se cita por el origen del término</strong>"},"cuidados":{"title":"En esta casa","info":"• La palabra <strong>siempre con su expediente</strong>: fecha y autor<br>• Y con su etiqueta: <strong>clásico de historia de las ideas</strong><br>• Nunca en una sola dirección: <strong>si señala, también se gira</strong>"}},"camara":{"nombre":"La cámara oscura","icon":"📷","estructura":{"title":"Qué es","info":"• De Marx y Engels, en <strong>«La ideología alemana»</strong><br>• Escrita <strong>1845 a 1846</strong>, publicada completa <strong>en 1932</strong><br>• La ideología <strong>invierte el mundo</strong>: las ideas dominantes son las de quien domina"},"funcion":{"title":"Cómo se reconoce","info":"• Manda preguntar <strong>a quién le conviene</strong> que algo parezca obvio<br>• Enseña que las ideas <strong>tienen dueño y dirección</strong><br>• Y que no caen del cielo: alguien gana con ellas"},"enfermedades":{"title":"Dónde se cae","info":"• Suponer <strong>una posición desde la que el mundo se ve derecho</strong>, sin decir cuál<br>• Aplicarlo solo hacia afuera: <strong>llave que abre todo menos la propia puerta</strong><br>• Citar la obra <strong>como si hubiera circulado desde 1846</strong>"},"cuidados":{"title":"En esta casa","info":"• Se usa la pregunta y <strong>se gira también hacia adentro</strong><br>• La fecha se dice completa: <strong>escrita en 1846, publicada en 1932</strong><br>• Y el Marx filósofo <strong>vive en su materia</strong>: aquí entra el concepto"}},"falsa":{"nombre":"La falsa conciencia","icon":"✉️","estructura":{"title":"Qué es","info":"• Creer con sinceridad <strong>lo que a otro le conviene</strong> que se crea<br>• Su <strong>fuente real</strong>: Engels, carta a <strong>Franz Mehring</strong><br>• Del <strong>14 de julio de 1893</strong>, y no de la obra publicada de Marx"},"funcion":{"title":"Cómo se reconoce","info":"• Nombra algo que existe: <strong>gente sincera creyendo lo que la daña</strong><br>• Explica por qué el argumento correcto <strong>a veces no mueve a nadie</strong><br>• Y viene siempre con su crítica pegada, <strong>el mismo día</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• Atribuirla a Marx: <strong>es un error de más de un siglo</strong><br>• <strong>Se autoinmuniza:</strong> toda objeción cuenta como síntoma<br>• Y quien la usa <strong>se declara despierto entre dormidos</strong>"},"cuidados":{"title":"En esta casa","info":"• Se cita <strong>en su fuente real, con fecha</strong><br>• El diagnóstico <strong>se paga</strong>: una creencia propia conveniente, esa noche<br>• Y nunca cierra una conversación: <strong>si la cierra, era arma</strong>"}},"mapa":{"nombre":"Del relacionismo al mapa","icon":"🗺️","estructura":{"title":"Qué es","info":"• <strong>Mannheim, «Ideología y utopía» (1929)</strong>: el que desenmascara también mira desde algún lado<br>• A eso lo llamó <strong>relacionismo</strong>, no relativismo<br>• <strong>Geertz (1964, en «La interpretación de las culturas», 1973)</strong>: es un <strong>mapa</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• Se declara <strong>el lugar propio</strong> y se sigue midiendo<br>• El mapa <strong>elige</strong>, y por eso sirve: deja cosas afuera<br>• Y aparece cuando <strong>los mapas heredados dejaron de servir</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• Confundirlo con relativismo: <strong>«todo da igual»</strong><br>• Creer que se puede mirar <strong>sin mapa</strong><br>• Tratar la ideología como <strong>enfermedad del vecino</strong>"},"cuidados":{"title":"En esta casa","info":"• La meta es <strong>tener las gafas a la vista</strong>, no quitárselas<br>• El mapa propio se escribe: <strong>núcleo, periferia y qué lo haría cambiar</strong><br>• Y el detector se prueba en casa: <strong>si no, es arma</strong>"}}};
let labParte='tracy',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== PREGUNTAS DE LAS LECTURAS =====================
// Tres baterías sobre los cinco textos: comprensión lectora (25, cinco por
// voz), completar (10) y análisis complejo (10). Los bancos se escriben desde
// _dev/inyecta-bancos-gafas-expediente.js, como todos los demás.
const lectComprensionBank=[{"t":"Borges","q":"¿Con qué fórmula descartaba a los demás el hombre del cuento?","o":["a) «Yo no tengo ideología; yo tengo sentido común»","b) «Todo es relativo, así que nada importa»","c) «Solo creo lo que puedo tocar»","d) «La política no me interesa»"],"c":0},{"t":"Borges","q":"Según el narrador, ¿para qué inventó Destutt de Tracy la palabra?","o":["a) Para insultar a los intelectuales de su tiempo","b) Para nombrar una ciencia sobre cómo se forman las ideas en cualquier cabeza","c) Para titular un manifiesto político","d) Para describir una enfermedad del entendimiento"],"c":1},{"t":"Borges","q":"El narrador dice que la palabra nació como…","o":["a) Un arma","b) Una bandera","c) Un espejo, y no como un dedo","d) Un dedo, y no como un espejo"],"c":2},{"t":"Borges","q":"¿Qué moraleja saca el narrador de la fábula del mapa del tamaño del imperio?","o":["a) Que los imperios siempre caen","b) Que los mapas grandes son más exactos","c) Que la cartografía es una ciencia inútil","d) Que un mapa sirve porque elige, y elegir es dejar cosas afuera"],"c":3},{"t":"Borges","q":"¿Por qué defendía su mapa con tanta fuerza el hombre del cuento?","o":["a) Porque no lo había visto nunca","b) Porque lo había estudiado a fondo","c) Porque se lo había enseñado un maestro","d) Porque lo había escrito él mismo"],"c":0},{"t":"Cervantes","q":"¿Con qué razón sostenía el arriero que la pieza era una bacía?","o":["a) Porque la había visto en un libro","b) Porque su padre había sido barbero en Almodóvar","c) Porque el ventero se lo había dicho","d) Porque la había comprado él mismo"],"c":1},{"t":"Cervantes","q":"Cuando los dos bandos se calentaron, ¿de qué pasaron a disputar?","o":["a) Del precio de la cena","b) De quién había llegado primero a la venta","c) De quién tenía los ojos limpios","d) Del dueño legítimo de la pieza"],"c":2},{"t":"Cervantes","q":"¿Para qué mandó traer don Quijote los antojos del ventero?","o":["a) Para leer una carta en voz alta","b) Para regalarlos al arriero","c) Para venderlos a tres reales","d) Para mostrar que no muda la pieza, sino el que mira"],"c":3},{"t":"Cervantes","q":"Según la sentencia de don Quijote, ¿dónde está el agravio?","o":["a) No en llevar antojos, que es forzoso, sino en jurar que no se llevan","b) En llevar antojos, porque el sabio mira desnudo","c) En no querer comprar antojos nuevos","d) En disputar con un arriero, que es de baja condición"],"c":0},{"t":"Cervantes","q":"¿Por qué el nombre «baciyelmo» acabó sirviendo a todos?","o":["a) Porque lo propuso el ventero, que era el dueño","b) Porque a nadie contentó del todo","c) Porque venía en los libros de caballerías","d) Porque era el más corto de los tres nombres"],"c":1},{"t":"Harari","q":"¿Qué diferencia pone el ensayo entre un chimpancé y un humano ante una frontera?","o":["a) El humano la respeta y el chimpancé la cruza","b) Los dos ven una línea, pero el humano la mide","c) El chimpancé ve pasto; el humano ve una patria","d) El chimpancé ve peligro; el humano ve comercio"],"c":2},{"t":"Harari","q":"¿Cuánto tiempo estuvo «La ideología alemana» sin publicarse completa?","o":["a) Diez años","b) Treinta años","c) Cincuenta años","d) Ochenta y seis años, de 1846 a 1932"],"c":3},{"t":"Harari","q":"Según el ensayo, ¿por qué es peligrosa la idea de falsa conciencia?","o":["a) Porque una teoría que explica cualquier respuesta no prohíbe ninguna","b) Porque nadie la entiende bien","c) Porque es demasiado antigua para servir","d) Porque la escribió Engels y no Marx"],"c":0},{"t":"Harari","q":"¿Qué hizo Mannheim en 1929 que, dice el ensayo, casi nadie hace?","o":["a) Publicar en dos idiomas a la vez","b) Apuntar el instrumento hacia sí mismo","c) Renunciar a su cátedra por una idea","d) Refutar a Marx con datos"],"c":1},{"t":"Harari","q":"¿Con qué compara el ensayo la promesa de «pensar sin ideología»?","o":["a) Con leer sin luz","b) Con nadar contra la corriente","c) Con caminar sin apoyar los pies","d) Con dibujar un mapa de memoria"],"c":2},{"t":"Entrevista","q":"¿Qué hizo Destutt de Tracy en la cárcel durante el Terror, según cuenta en la entrevista?","o":["a) Escribió los «Elementos de ideología»","b) Leyó a Locke y a Condillac y salió con la urgencia de entender cómo se fabrican las ideas","c) Planeó su venganza contra Napoleón","d) Enseñó a leer a los demás presos"],"c":1},{"t":"Entrevista","q":"¿Por qué subraya Tracy lo de «cualquier cabeza» al explicar su ciencia de 1796?","o":["a) Porque quería estudiar solo a los gobernantes","b) Porque las cabezas ilustradas piensan mejor","c) Porque su ciencia era solo para los ignorantes","d) Porque el que estudia queda dentro del estudio: la palabra nació como espejo, no como dedo"],"c":3},{"t":"Entrevista","q":"Según Tracy, ¿qué hace en realidad quien dice «yo no tengo ideología, yo tengo sentido común»?","o":["a) Lo mismo que Napoleón: reserva la palabra para el adversario y reclama para sí la realidad entera","b) Un ejercicio sano de humildad","c) Una cita correcta de los «Elementos de ideología»","d) Una defensa del relacionismo de Mannheim"],"c":0},{"t":"Entrevista","q":"¿Qué regla de método regala Tracy a los oyentes a propósito del cajón de 1932?","o":["a) Que los manuscritos deben publicarse enseguida","b) Que ningún manuscrito debe guardarse en cajones","c) Que una idea viaja con dos fechas: la de escritura explica al autor y la de publicación explica los efectos","d) Que los libros viejos ya no influyen en nadie"],"c":2},{"t":"Entrevista","q":"Si volviera a 1796, ¿qué haría Tracy con su palabra?","o":["a) No la acuñaría: elegiría otra menos peligrosa","b) Se la regalaría a Napoleón para hacer las paces","c) La escondería hasta tiempos mejores","d) La acuñaría otra vez, con una advertencia grabada: funciona solamente apuntando hacia el que la usa"],"c":3},{"t":"Quintero y Gala","q":"¿Qué contesta Gala cuando Quintero le pregunta si tiene ideología?","o":["a) Que la abandonó al salir de Córdoba","b) Que nunca ha tenido: el poeta mira desnudo","c) Que la tiene como tiene hígado: trabajando día y noche sin que él la vea","d) Que solo tienen ideología los políticos"],"c":2},{"t":"Quintero y Gala","q":"¿Con qué imagen resume Gala el destino de la palabra de Destutt de Tracy?","o":["a) Bautizó un espejo y le creció un dedo: quiso una ciencia y le nació un insulto","b) Sembró un árbol y recogió tormentas","c) Encendió una lámpara y llegó la noche","d) Escribió una carta que nadie contestó"],"c":0},{"t":"Quintero y Gala","q":"¿Qué aprendió Gala charlando con su perro Troylo?","o":["a) Que los perros también llevan gafas","b) Que nadie elige su estatura, y lo honrado es confesar desde dónde se mira","c) Que desde abajo no se ve nada","d) Que las grandezas humanas son eternas"],"c":1},{"t":"Quintero y Gala","q":"¿Con qué compara Gala el libro que durmió ochenta y seis años en un cajón?","o":["a) Con un tesoro enterrado","b) Con un vino que mejora en la bodega","c) Con un reloj parado","d) Con una carta de amor entregada al viudo"],"c":3},{"t":"Quintero y Gala","q":"¿Cuál es el aforismo con que Gala cierra la conversación?","o":["a) Quien mucho abarca poco aprieta","b) Cada uno cuenta de la feria según le va en ella","c) La ceguera no es llevar gafas: es jurar que se mira a ojo desnudo; quien confiesa sus gafas empieza a ver","d) Más vale pájaro en mano que buitre volando"],"c":2}];
const lectCompletarBank=[{"t":"las cinco","q":"La palabra «ideología» se acuñó hacia el año ___.","a":"1796"},{"t":"Borges","q":"El narrador dice que la palabra nació como un ___, y no como un dedo.","a":"espejo"},{"t":"Borges y Harari","q":"La frase «falsa conciencia» está en una carta de Engels a Franz ___.","a":"Mehring"},{"t":"Borges y Harari","q":"Esa carta es del 14 de julio de ___.","a":"1893"},{"t":"Cervantes","q":"El arriero sostenía que la pieza de bronce era una ___ de barbero.","a":"bacía"},{"t":"Cervantes","q":"El estudiante sostenía, en cambio, que era un ___.","a":"yelmo"},{"t":"Cervantes","q":"Don Quijote mandó traer unos ___ para probar su sentencia.","a":"antojos"},{"t":"Cervantes","q":"El nombre en que quedaron todos de acuerdo fue ___.","a":"baciyelmo"},{"t":"Harari","q":"«La ideología alemana» no se publicó completa hasta ___.","a":"1932"},{"t":"Harari","q":"Mannheim, que era judío, tuvo que abandonar Alemania en ___.","a":"1933"}];
const lectAnalisisBank=[{"q":"1. El cuento, el capítulo y el ensayo cuentan el mismo expediente. Explica qué hace cada voz que las otras dos no pueden hacer, y qué se perdería si se leyera solo una.","guia":"El cuento instala la idea como imagen que no se olvida: el hombre que llevaba su mapa doblado en el bolsillo y lo defendía porque no lo había visto nunca. El capítulo la vuelve escena y risa, y por eso se recuerda con el cuerpo: la misma pieza de bronce vista como bacía o como yelmo, y Sancho vendiendo antojos de vidrio mientras su amo habla de los del entendimiento. El ensayo la pone a escala de especie y con fechas comprobables, y por eso se puede citar. Quien lee solo una se queda sin una de las tres cosas: la imagen, la escena o la prueba, y las tres hacen falta, porque el concepto tiene que sobrevivir a la memoria, a la conversación y al examen."},{"q":"2. El hombre del cuento y los dos bandos de la venta cometen el mismo error con nombres distintos. Nómbralo en una frase y di qué prueba usaría cada autor para demostrárselo.","guia":"El error es el mismo: creer que se mira sin nada delante de los ojos, y por tanto llamar verdad al mapa propio y antojos al del vecino. La prueba de Borges es histórica: enseñarle que la palabra con que descarta a los otros nació en 1796 para estudiar todas las cabezas, incluida la suya. La prueba de Cervantes es física y mucho más rápida: pone los antojos sobre la mesa, todos ven la pieza igual, y con eso queda claro que lo que cambia es el que mira y no la pieza. La de Harari es estadística y de escala: si millones de personas ven patria donde un chimpancé ve pasto, el mapa está en la cabeza, y quien afirma no tenerlo tendría que explicar por qué es la única excepción de la especie."},{"q":"3. Traduce la sentencia de don Quijote («el agravio no está en llevarlos, sino en jurar que no se llevan») al vocabulario de Mannheim, y explica por qué relacionismo no es relativismo.","guia":"La traducción: llevar antojos es la condición de mirar, así que no es un defecto que se pueda corregir; lo que sí es un defecto es negarlo, porque quien niega su posición se pone fuera del examen y deja de poder ser corregido. Eso es exactamente lo que Mannheim aceptó en 1929: si toda posición social produce su punto de vista, el que desenmascara también mira desde algún lado, y por eso hay que declarar el lugar propio. No es relativismo porque declarar el lugar no iguala los mapas: dos mapas parciales del mismo terreno siguen siendo comparables, y uno llega al río. El relativismo abandona el juicio; el relacionismo lo conserva y le exige domicilio."},{"q":"4. El ensayo llama a la falsa conciencia «un arma cómoda y un instrumento inútil». Explica las dos mitades por separado y aplica la crítica a un caso de esta casa.","guia":"Arma cómoda: permite ganar cualquier discusión sin escuchar, porque el desacuerdo del otro se reclasifica como síntoma y no como razón; y encima se siente como lucidez, que es lo que la hace tan barata. Instrumento inútil: una explicación que da cuenta de cualquier respuesta posible (si asiente, tiene conciencia clara; si objeta, tiene conciencia falsa) no prohíbe ninguna, y lo que no prohíbe nada no informa de nada. El caso de la casa es el de Jael despachando al tío: la frase cerró la conversación, que era lo único que había que conservar. La corrección tiene dos partes, la de fuente (es de Engels, en su carta a Mehring del 14 de julio de 1893, no de la obra publicada de Marx) y la de método: quien diagnostica paga el diagnóstico esa misma noche con una creencia propia que le convenga creer."},{"q":"5. ¿Por qué el dato de que «La ideología alemana» durmió ochenta y seis años cambia la manera de citarla? Escribe una cita mal fechada y su corrección.","guia":"Porque una obra publicada en 1932 no pudo influir en los debates de 1848, 1871 ni 1900, y media discusión del siglo veinte se hizo con un libro que los protagonistas del siglo diecinueve nunca leyeron. Citarla como si hubiera circulado desde 1846 inventa una cadena de influencia que no existió. Cita mal fechada: «desde 1846, la tesis de la cámara oscura organizó el debate europeo sobre las ideas». Corrección: «la tesis de la cámara oscura fue escrita en 1845 y 1846, pero solo pudo organizar debates a partir de 1932, cuando el manuscrito se publicó completo». La regla general que sale de aquí: la fecha de escritura explica al autor, y la fecha de publicación explica los efectos; confundirlas es fabricar historia."},{"q":"6. El cuento, el capítulo y el ensayo rechazan la misma salida cómoda. Reconstruye la mejor versión de esa salida, en su forma más fuerte, y contéstala.","guia":"La mejor versión, que hay que poner en pie antes de tocarla como manda la regla del acero: si toda mirada viene de una posición y ninguna es neutral, entonces cualquier juicio es una posición más, incluido este; pretender arbitrar entre mapas es solo imponer el mapa propio con mejores modales, así que lo honesto es abstenerse. La respuesta tiene tres piezas. Una, la de Mannheim: la parcialidad de origen no implica igualdad de valor, y él nombró esa diferencia relacionismo justamente para que no se confundiera. Dos, la de Geertz: los mapas se comparan por lo que permiten hacer, y algunos permiten llegar al río; el criterio no desaparece, cambia de sitio. Tres, la práctica: la abstinencia no es neutral, porque quien se abstiene le deja el juicio a quien grite más fuerte, y eso también es un resultado político."},{"q":"7. En el cuento, el narrador dice que el error del hombre «es el mío en los días en que me distraigo». Explica por qué ese renglón hace legítimo el resto del cuento, y qué le pasa a un texto que no lo trae.","guia":"Porque sin ese renglón el cuento sería lo que dice criticar: un texto que reparte ceguera hacia afuera desde una posición que no se examina, es decir el uso napoleónico de la palabra con mejor prosa. Con ese renglón el narrador se incluye en el diagnóstico, y entonces la observación deja de ser una insignia de superioridad y pasa a ser un instrumento que también lo mide a él. Un texto que no lo trae puede ser brillante y sigue siendo un arma: se lee con placer, no cambia a nadie que no estuviera de acuerdo, y produce lectores que aprenden a ver gafas ajenas y se creen descalzos, que es la trampa propia de esta materia. La regla de la casa es esa misma en formato de contabilidad: un desenmascaramiento propio por cada uno ajeno."},{"q":"8. ¿Cuál de las tres primeras lecturas (el cuento, el capítulo o el ensayo) convencería mejor a alguien que dice «yo no soy ideológico, soy pragmático»? Defiende tu elección citando una frase del texto que elegiste.","guia":"Cualquiera de las tres se acepta si la defensa es buena, y lo que se corrige es el argumento, no la elección. La defensa más frecuente y más sólida es la del capítulo cervantino, porque el pragmático no discute con teoría sino con evidencia inmediata, y la escena se la da: los antojos se ponen sobre la mesa, todos ven la pieza igual, y la frase que remata es «no es la pieza la que muda, sino el que mira». Además no lo humilla: don Quijote dice que llevar antojos es forzoso, así que el pragmático no queda como tonto sino como normal. La defensa del ensayo es buena si se apoya en el dato de escala (chimpancé y frontera) y la del cuento si se apoya en el retrato final, el hombre que murió convencido de su transparencia; lo que no se acepta es elegir sin citar, porque entonces no se leyó."},{"q":"9. El «baciyelmo» es un acuerdo que a nadie contentó del todo. Discute si sirve como modelo para las fichas de M.E.T.A.S o si es una trampa, y con qué condición.","guia":"Sirve y es trampa, según qué se esté nombrando, y la respuesta buena distingue las dos cosas. Sirve cuando el pleito es de vocabulario y no de hechos: si dos lados llaman de distinto modo a lo mismo, un término que no cierre por debajo (prosa llana en vez del término de un glosario) deja la disputa a la vista en vez de resolverla a favor de uno, y eso es exactamente lo que la casa pidió en el caso del glosario de L 60,000. Es trampa cuando se usa para no decidir un asunto de hecho: si la pregunta es qué dice la Constitución de 1982 o quién paga el proyecto, inventar una palabra intermedia no es prudencia, es niebla, y la niebla siempre favorece al que ya tenía el poder. La condición: el baciyelmo vale para nombrar, nunca para describir, y en la ficha va con las dos lecturas al lado."},{"q":"10. Las cinco lecturas llevan la etiqueta de ejercicio de estilo de la casa. Explica por qué esa etiqueta es parte del temario y no un trámite, y qué pasaría si se quitara.","guia":"Porque la materia entera enseña a pedir fuente, fecha y estatus, y un texto que imita la voz de Borges sin declararlo sería una fuente inflada dentro de la propia clase: enseñaría la regla y la rompería en la misma página, que es la manera más rápida de perder la autoridad para exigirla. Y porque el pastiche declarado hace visible algo que la etapa quiere enseñar: la voz también es un mapa, y una idea suena más verdadera dicha con la prosa de un clásico, así que conviene saber cuándo lo que convence es el argumento y cuándo el timbre. Si se quitara, pasarían dos cosas: alguien citaría a Borges diciendo algo que Borges no escribió, y la casa quedaría produciendo exactamente el tipo de material que su compendio manda cazar. De ahí la regla extra: la voz es el único artificio permitido, y toda obra, fecha y persona de dentro es real y comprobable."}];
const xpLect={c:new Set(),f:new Set()};

/* ---------- I. Comprensión lectora ---------- */
let lcIdx=0,lcSel=-1,lcDone=false;
function showLectC(){const cont=document.getElementById('lcQ');if(!cont)return;if(lcIdx>=lectComprensionBank.length){cont.textContent='🎉 ¡Comprensión lectora completada!';document.getElementById('lcOpts').innerHTML='';document.getElementById('lcProg').textContent='Las '+lectComprensionBank.length+' preguntas respondidas';unlockAchievement('lect_master');return;}const q=lectComprensionBank[lcIdx];document.getElementById('lcProg').textContent='Pregunta '+(lcIdx+1)+' de '+lectComprensionBank.length+' · '+q.t;cont.textContent=q.q;const opts=document.getElementById('lcOpts');opts.innerHTML='';lcSel=-1;lcDone=false;q.o.forEach((o,i)=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=o;b.onclick=()=>{if(lcDone)return;opts.querySelectorAll('.qz-opt').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');lcSel=i;sfx('click');};opts.appendChild(b);});}
function checkLectC(){if(lcIdx>=lectComprensionBank.length)return;if(lcSel<0)return fb('fbLC','Selecciona una respuesta.',false);lcDone=true;const opts=document.querySelectorAll('#lcOpts .qz-opt');if(lcSel===lectComprensionBank[lcIdx].c){opts[lcSel].classList.add('correct');fb('fbLC','¡Correcto! +2 XP',true);if(!xpLect.c.has(lcIdx)){xpLect.c.add(lcIdx);pts(2);}sfx('ok');}else{opts[lcSel].classList.add('wrong');opts[lectComprensionBank[lcIdx].c].classList.add('correct');fb('fbLC','Incorrecto. Vuelve al texto: la respuesta está ahí.',false);sfx('no');}setTimeout(()=>{lcIdx++;showLectC();},1700);}
function resetLectC(){sfx('click');lcIdx=0;showLectC();document.getElementById('fbLC').classList.remove('show');}

/* ---------- II. Completar ---------- */
let lfIdx=0;
function showLectF(){const cont=document.getElementById('lfQ');if(!cont)return;if(lfIdx>=lectCompletarBank.length){cont.innerHTML='🎉 ¡Las diez oraciones completadas!';document.getElementById('lfProg').textContent='Terminado';const inp=document.getElementById('lfInput');if(inp)inp.style.display='none';return;}const d=lectCompletarBank[lfIdx];document.getElementById('lfProg').textContent='Oración '+(lfIdx+1)+' de '+lectCompletarBank.length+' · '+d.t;cont.innerHTML=d.q.replace('___','<span class="blank">___</span>');const inp=document.getElementById('lfInput');if(inp){inp.style.display='';inp.value='';inp.classList.remove('eval-input-ok','eval-input-no');}}
function checkLectF(){if(lfIdx>=lectCompletarBank.length)return;const inp=document.getElementById('lfInput');const d=lectCompletarBank[lfIdx];if(!inp.value.trim())return fb('fbLF','Escribe tu respuesta.',false);const ok=isCpCorrect(inp.value,d.a);inp.classList.toggle('eval-input-ok',ok);inp.classList.toggle('eval-input-no',!ok);if(ok){fb('fbLF','¡Correcto! +2 XP',true);if(!xpLect.f.has(lfIdx)){xpLect.f.add(lfIdx);pts(2);}sfx('ok');}else{fb('fbLF','Todavía no. La respuesta esperada era: '+d.a,false);sfx('no');}setTimeout(()=>{lfIdx++;showLectF();document.getElementById('fbLF').classList.remove('show');},1900);}
function resetLectF(){sfx('click');lfIdx=0;showLectF();document.getElementById('fbLF').classList.remove('show');}

/* ---------- III. Análisis complejo ---------- */
let laIdx=0,laPautaVisible=false;
function showLectA(){const cont=document.getElementById('laQ');if(!cont)return;const d=lectAnalisisBank[laIdx];document.getElementById('laProg').textContent='Pregunta '+(laIdx+1)+' de '+lectAnalisisBank.length;cont.textContent=d.q;const p=document.getElementById('laPauta');p.innerHTML='<strong>Pauta:</strong> '+d.guia;p.style.display=laPautaVisible?'block':'none';document.getElementById('laTA').value='';}
function nextLectA(){sfx('click');laIdx=(laIdx+1)%lectAnalisisBank.length;showLectA();}
function prevLectA(){sfx('click');laIdx=(laIdx-1+lectAnalisisBank.length)%lectAnalisisBank.length;showLectA();}
function toggleLectAPauta(){sfx('click');laPautaVisible=!laPautaVisible;const p=document.getElementById('laPauta');p.style.display=laPautaVisible?'block':'none';const b=document.getElementById('btnLectAPauta');if(b)b.textContent=laPautaVisible?'🙈 Ocultar pauta':'👁 Ver pauta';}

/* ---------- impresión: cada lectura por separado ---------- */
// La etiqueta del estatus viaja SIEMPRE con el texto impreso: una hoja
// suelta con un pastiche sin declarar es exactamente la fuente inflada que
// el Estudio Mayor enseña a cazar.
const LECTURAS_IMPR={
  borges:{titulo:'El hombre que miraba sin gafas',tipo:'Cuento, a la manera de Jorge Luis Borges'},
  cervantes:{titulo:'De la reñida disputa sobre si era bacía o yelmo',tipo:'Capítulo, a la manera de Miguel de Cervantes Saavedra'},
  harari:{titulo:'Los mapas invisibles',tipo:'Ensayo, a la manera de Yuval Noah Harari'},
  // Las dos entrevistas llevan bandera de ficción: su etiqueta impresa tiene
  // que decir que el encuentro nunca ocurrió, no solo que la voz es imitada,
  // porque una hoja suelta viaja sola y sin la nota de pantalla.
  entrevista:{titulo:'La palabra devuelta a su dueño',tipo:'Entrevista imaginada con Antoine Destutt de Tracy, a la manera de Iñaki Gabilondo',ficcion:true},
  gala:{titulo:'Nadie mira a ojo desnudo',tipo:'Conversación imaginada: Jesús Quintero y Antonio Gala (El Loco de la Colina)',ficcion:true},
};
function _hojaImpresa(titulo,cuerpo,pieExtra){
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${titulo} · La palabra con expediente · F.A.R.O.</title><style>
@page{size:letter;margin:16mm 15mm;}
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:Georgia,'Times New Roman',serif;font-size:11.5pt;line-height:1.55;color:#111;background:#fff;}
h1{font-family:Arial,Helvetica,sans-serif;font-size:15pt;color:#3b1580;margin-bottom:2mm;line-height:1.2;}
.tipo{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;color:#555;margin-bottom:3mm;}
.ruta{font-family:Arial,Helvetica,sans-serif;font-size:9pt;color:#5b21b6;border-bottom:1.5pt solid #5b21b6;padding-bottom:1.5mm;margin-bottom:3mm;display:flex;justify-content:space-between;gap:6mm;}
.etiqueta{border:1.2pt solid #5b21b6;background:#f5f3ff;border-radius:2mm;padding:2.5mm 3mm;font-family:Arial,Helvetica,sans-serif;font-size:9pt;line-height:1.4;margin-bottom:4mm;}
.idline{font-family:Arial,Helvetica,sans-serif;font-size:9pt;display:flex;gap:4mm;margin-bottom:3mm;}
.idline span.r{flex:1;border-bottom:0.8pt solid #666;}
p.t{text-align:justify;margin-bottom:2.6mm;text-indent:6mm;}
p.t:first-of-type{text-indent:0;}
h2{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#3b1580;margin:4mm 0 2mm;}
.sec{font-family:Arial,Helvetica,sans-serif;font-size:10.5pt;font-weight:700;color:#5b21b6;background:#f5f3ff;border-left:3pt solid #5b21b6;padding:1.2mm 2.5mm;margin:4mm 0 2mm;}
.q{font-family:Arial,Helvetica,sans-serif;font-size:10pt;margin:2mm 0 1mm;}
.q .n{font-weight:700;color:#5b21b6;}
.op{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;margin-left:7mm;}
.ln{border-bottom:0.8pt solid #888;height:6.5mm;}
.ln-alta{border-bottom:0.8pt solid #888;height:9mm;}
.fuente{font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;font-style:italic;}
.pauta{page-break-before:always;}
.pl{font-family:Arial,Helvetica,sans-serif;font-size:9pt;margin-bottom:1.6mm;text-align:justify;}
.pie{border-top:0.8pt solid #999;margin-top:5mm;padding-top:2mm;font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;display:flex;justify-content:space-between;gap:6mm;}
</style></head><body>${cuerpo}<div class="pie"><span>🏠 Proyecto Educativo F.A.R.O. · Estudio Mayor</span><span>👓 La palabra con expediente${pieExtra||''}</span></div></body></html>`;
}
function _abreImpresion(doc){
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}
function imprimirLectura(clave){
  const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
  if(!meta||!card){showToast('⚠️ No se encontró la lectura');return;}
  sfx('click');
  const nota=card.querySelector('.lect-nota');
  const parrafos=[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  // La etiqueta cambia con el género: un pastiche declara la voz prestada; una
  // entrevista declara además que el encuentro nunca ocurrió (norma 5-quinquies).
  const etiqueta=meta.ficcion
    ?`<div class="etiqueta"><strong>⚠️ Entrevista imaginada: el encuentro nunca ocurrió.</strong> Las personas son reales, pero este texto <strong>NO recoge sus palabras</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando sus voces, en homenaje, y se declara como ficción. Regla extra de la casa: <strong>toda obra, fecha y cifra citada dentro del texto es real y comprobable</strong>; lo único inventado es la conversación.</div>`
    :`<div class="etiqueta"><strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Este texto <strong>NO es obra de ese autor</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando su voz, y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro del texto es real y comprobable</strong>; el único artificio permitido es la voz.</div>`;
  const cuerpo=`<div class="ruta"><span>👓 Ruta de las Gafas a la Vista · Etapa 1 de 7</span><span>Lecturas 📖</span></div>`
    +`<h1>${meta.titulo}</h1><div class="tipo">${meta.tipo}</div>`
    +etiqueta
    +`<div class="idline"><span>Lee:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
    +parrafos;
  _abreImpresion(_hojaImpresa(meta.titulo,cuerpo,' · '+meta.titulo));
}
function imprimirTodasLasLecturas(){
  sfx('click');
  let cuerpo=`<div class="ruta"><span>👓 Ruta de las Gafas a la Vista · Etapa 1 de 7</span><span>Las cinco lecturas 📖</span></div>`
    +`<h1>Las cinco lecturas de «La palabra con expediente»</h1><div class="tipo">Un cuento, un capítulo de caballerías, un ensayo y dos entrevistas imaginadas, sobre el mismo expediente</div>`
    +`<div class="etiqueta"><strong>⚠️ Ejercicios de estilo de la casa, en homenaje.</strong> Los cinco textos <strong>NO son obra de Jorge Luis Borges, de Miguel de Cervantes Saavedra ni de Yuval Noah Harari</strong>, y las dos entrevistas son <strong>encuentros que nunca ocurrieron</strong>: las voces de Iñaki Gabilondo, Antoine Destutt de Tracy, Jesús Quintero y Antonio Gala se imitan en homenaje, y lo único inventado es la conversación. Todo lo escribió el Proyecto Educativo F.A.R.O. y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro de los textos es real y comprobable</strong>; el único artificio permitido es la voz.</div>`;
  ['borges','cervantes','harari','entrevista','gala'].forEach((clave,i)=>{
    const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
    if(!card)return;
    const nota=card.querySelector('.lect-nota');
    cuerpo+=(i?'<div style="page-break-before:always;"></div>':'')
      +`<h2>${i+1}. ${meta.titulo}</h2><div class="tipo">${meta.tipo}</div>`
      +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
      +[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  });
  _abreImpresion(_hojaImpresa('Las cinco lecturas',cuerpo,' · Las cinco lecturas'));
}
function imprimirPreguntasLecturas(){
  sfx('click');
  const lineas=(n,alta)=>Array(n).fill('<div class="'+(alta?'ln-alta':'ln')+'"></div>').join('');
  let cuerpo=`<div class="ruta"><span>👓 Ruta de las Gafas a la Vista · Etapa 1 de 7</span><span>Preguntas de las lecturas 📖</span></div>`
    +`<h1>Preguntas de las cinco lecturas</h1><div class="tipo">La palabra con expediente · 25 de comprensión lectora, 10 de completar y 10 de análisis complejo</div>`
    +`<div class="idline"><span>Nombre:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +`<div class="etiqueta">Se responde <strong>con los cinco textos delante</strong>: no es un examen de memoria. Las respuestas de las tres secciones van en la <strong>pauta de la última hoja</strong>, así que se resuelve antes de darle la vuelta. Los cinco textos son <strong>ejercicios de estilo de la casa, no obra de Borges, Cervantes ni Harari; las dos entrevistas son encuentros que nunca ocurrieron</strong>.</div>`;
  cuerpo+='<div class="sec">I. Comprensión lectora (25 preguntas)</div>';
  lectComprensionBank.forEach((q,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${q.q} <span class="fuente">(${q.t})</span></div>`;
    q.o.forEach(o=>{cuerpo+=`<div class="op">${o}</div>`;});
  });
  cuerpo+='<div class="sec">II. Completa la oración (10 preguntas)</div>';
  lectCompletarBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q.replace('___','_______________')} <span class="fuente">(${d.t})</span></div>`;
  });
  cuerpo+='<div class="sec">III. Análisis complejo (10 preguntas)</div>';
  lectAnalisisBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q}</div>`+lineas(3,true);
  });
  cuerpo+='<div class="pauta"><div class="sec">✅ Pauta completa de respuestas</div>';
  cuerpo+='<div class="pl"><strong>I. Comprensión lectora:</strong> '+lectComprensionBank.map((q,i)=>(i+1)+') '+'abcd'[q.c]).join(' · ')+'</div>';
  cuerpo+='<div class="pl"><strong>II. Completar:</strong> '+lectCompletarBank.map((d,i)=>(i+1)+') '+d.a).join(' · ')+'</div>';
  cuerpo+='<div class="pl" style="margin-top:2mm;"><strong>III. Análisis complejo (guías de corrección):</strong></div>';
  lectAnalisisBank.forEach((d,i)=>{cuerpo+=`<div class="pl"><strong>${i+1}.</strong> ${d.guia}</div>`;});
  cuerpo+='</div>';
  _abreImpresion(_hojaImpresa('Preguntas de las lecturas',cuerpo,' · Preguntas de las lecturas'));
}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue abriendo el expediente!','¡Muy buen trabajo!','¡Aprendiz de óptico!','¡Ya distingues expediente de insulto!','¡Con las gafas a la vista!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='👓 ¡'+name+' completó la Etapa 1 de la Ruta de las Gafas a la Vista (La palabra con expediente)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

